from typing import List, Dict, Union
from json import loads

from taf.gnb.oam.coam.vdu.exceptions import WrongApiResponseStatus

from taf.rfrl.procedures.resources.python.bts.config.config import Config
from taf.rfrl.procedures.resources.python.bts.utils.timer import wait_for
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import Api
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UnsupportedConfig, UnexpectedConfig


class ConfigDu(Config):
    """ Represents BTS DU configuration (parameters and their values) which can be stored in form of SCF file. """

    def __init__(self, mrbts_id: str, nrbts_id: str, api: Api, api_alias: str):
        """
        :param mrbts_id: ID of MRBTS which will be present in this configuration; i.e. '8442' for MRBTS-8442
        :param nrbts_id: ID of NRBTS which will be present in this configuration; i.e. '8442' for NRBTS-8442
        :param api: API used for performing operations on this configuration
        :param api_alias: name of opened API connection which this configuration should use
        """
        super(ConfigDu, self).__init__(mrbts_id,
                                       nrbts_id,
                                       api,
                                       api_alias)

    @pretty_log
    def get(self, dist_name: str, param: str) -> str:
        """
        Returns value of given parameter from current configuration.
        :param dist_name: dist name of Managed Object which contains given parameter;
                          two formats are allowed:
                          1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                          2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                             MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
        :param param: name of parameter for which values should be read
        :return: value of given parameter
        :raises UnsupportedConfig: if param with given name doesn't exist under given dist name
        """
        dist_name = self._format_dist_name(dist_name)
        log_info(f'Getting value from config: dist_name={dist_name}, param={param}', to_console=True)

        try:
            value = self._api.search_parameter_of_current_plan(para_name=param,
                                                               mo_dn=dist_name,
                                                               vdu_connection=self._api_alias)
            log_debug(f'Value from config: dist_name={dist_name}, param={param}, value={value}')
            return value
        except WrongApiResponseStatus:
            raise UnsupportedConfig(f'Parameter does not exist: dist_name={dist_name}, param={param}')

    @pretty_log
    def get_many(self, dist_names: List[str], log_to_console: bool = True) -> Dict[str, Dict[str, Union[str, List, Dict]]]:
        """
        Returns values of all parameters under given dist names from current config.
        :param dist_names: dist names of Managed Objects which parameters will be returned;
                           two formats are allowed:
                           1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                           2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                              MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
        :param log_to_console: defines whether to log info message to console about getting parameters;
                               defaults to True
        :return: values of all parameters under given dist names;
                 i.e. {'MRBTS-1/NRBTS-1/NRDU-1': {'actualStartTime': '04.10.2024 07:31:37',
                                                  'fPdcchMonOccsnPo': ['2', '3'],
                                                  'rfAntResults': [{'vswr': '1.2',
                                                                    'rssi': '-140'},
                                                                   {'vswr': '1.5',
                                                                    'rssi': '-142'}]},
                       'MRBTS-1/NRBTS-1/NRDU-2': {'actualStartTime': '04.10.2024 07:31:37',
                                                  'fPdcchMonOccsnPo': ['2', '3'],
                                                  'rfAntResults': {'vswr': '1.2',
                                                                   'rssi': '-140'}}}
        :raises UnsupportedConfig: if any of given dist names doesn't exist
        """
        dist_names = [self._format_dist_name(dist_name) for dist_name in dist_names]
        log_info(f'Getting multiple values from config: dist_names={dist_names}', to_console=log_to_console)

        try:
            api_objects = self._api.get_current_plan_objects(dist_names=dist_names,
                                                             vdu_connection=self._api_alias)
        except WrongApiResponseStatus:
            raise UnsupportedConfig(f'One of given dist names: {dist_names} does not exist')

        log_debug(f'Objects read from API: {api_objects}')
        unpacked_values = {}
        self._unpack_values_read_from_api(api_objects, unpacked_values)
        log_debug(f'Values from config objects: {unpacked_values}')
        return unpacked_values

    @pretty_log
    def get_many_by_class_names(self, dist_name: str, class_names: List[str]) -> Dict[str, Dict[str, Union[str, List, Dict]]]:
        """
        Returns values of all parameters from Managed Objects of given classes which are under given dist name in current config.
        :param dist_name: dist name of Managed Object which should contain Managed Objects of given classes;
                          two formats are allowed:
                          1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                          2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                             MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
        :param class_names: classes of Managed Objects which parameters will be returned;
                            i.e. ['CLOCK_R', 'PMMNL'] for MRBTS-{}/MNL-1/MNLENT-1 dist name
        :return: values of all parameters from Managed Objects of given classes which are under given dist name;
                 i.e. {'MRBTS-1/MNL-1/MNLENT-1/SYNC-1/CLOCK-1/CLOCK_R-1': {'syncStatus': 'Locked',
                                                                           'targetDN': 'MRBTS-1/EQM-1/APEQM-1/RMOD-1'},
                       'MRBTS-1/MNL-1/MNLENT-1/PMMNL-1': {'eCpriMasterStatisticsInterval': '15min',
                                                          'miGnssTimeError': 'disabled'}}
        :raises UnsupportedConfig: if given dist name doesn't exist
        """
        dist_name = self._format_dist_name(dist_name)
        log_info(f'Getting multiple values from config: dist_name={dist_name}, class_names={class_names}', to_console=True)

        try:
            api_objects = self._api.get_current_plan_objects(ancestor_dist_name=dist_name,
                                                             class_name=class_names,
                                                             vdu_connection=self._api_alias)
        except WrongApiResponseStatus:
            raise UnsupportedConfig(f'Dist name {dist_name} does not exist')

        log_debug(f'Objects read from API: {api_objects}')
        unpacked_values = {}
        self._unpack_values_read_from_api(api_objects, unpacked_values)
        log_debug(f'Values from config objects: {unpacked_values}')
        return unpacked_values

    @pretty_log
    def set(self, dist_name: str, param: str, value: str, wait: bool = True):
        """
        Changes value of given parameter from current configuration to the new one.
        If requested value is already set then nothing will be done.
        :param dist_name: dist name of Managed Object which contains given parameter;
                          two formats are allowed:
                          1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                          2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                             MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
        :param param: name of parameter for which value should be set
        :param value: new value of parameter which will be set
        :param wait: defines whether to wait for successful recommissioning;
                     use False if changing parameter value will result in DU reset, True otherwise;
                     defaults to True
        :raises TimeExceeded: if any step of setting new parameter value exceeds defined timeout
        :raises ResultError: if any step of setting new parameter value fails
        """
        dist_name = self._format_dist_name(dist_name)
        log_info(f'Setting value in config: dist_name={dist_name}, param={param}, value={value}', to_console=True)

        if self._is_value_already_set(value, param, dist_name):
            log_debug(f'Value already set: dist_name={dist_name}, param={param}, value={value}')
            return

        delta = [{'distName': dist_name,
                  'operation': 'update',
                  'parameters': [{'parameterName': param,
                                  'operation': 'update',
                                  'value': value}]}]
        self._perform_delta_recommissioning(delta, wait)

    @pretty_log
    def set_many(self, params_values: List[Dict[str, str]], wait: bool = True):
        """
        Changes values of given parameters from current configuration to the new ones.
        All values will be changed at once in a single configuration plan.
        If any requested value is already set then it will not be set again.
        If all requested values are already set then nothing will be done.
        :param params_values: collection of:
                              * dist names of Managed Objects which contains given parameter,
                                two formats are allowed:
                                1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                                2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                                   MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
                              * names of parameters for which values should be set,
                              * new values of parameters which will be set;
                              i.e. [{'dist_name': 'MRBTS-1/NRBTS-1/NRDU-1',
                                     'param': 'actFdmScheduling',
                                     'value': 'true'},
                                    {'dist_name': 'MRBTS-1/NRBTS-1/NRDU-2',
                                     'param': 'actFdmEnhancedScheduling',
                                     'value': 'false'}]
        :param wait: defines whether to wait for successful recommissioning;
                     use False if changing any parameter value will result in DU reset, True otherwise;
                     defaults to True
        :raises TimeExceeded: if any step of setting new parameters values exceeds defined timeout
        :raises ResultError: if any step of setting new parameters values fails
        """
        log_info('Setting multiple values in config', to_console=True)
        params_values_not_set_yet = self._get_params_values_not_set_yet(params_values)

        if params_values_not_set_yet:
            delta = []

            for param_value in params_values_not_set_yet:
                dist_name = self._format_dist_name(param_value['dist_name'])
                delta_parameters_item = {'parameterName': param_value['param'],
                                         'operation': 'update',
                                         'value': param_value['value']}

                for delta_item in delta:
                    if delta_item['distName'] == dist_name:
                        delta_item['parameters'].append(delta_parameters_item)
                        break
                else:
                    delta.append({'distName': dist_name,
                                  'operation': 'update',
                                  'parameters': [delta_parameters_item]})

            self._perform_delta_recommissioning(delta, wait)

    @pretty_log
    def set_and_expect_error(self, dist_name: str, param: str, value: str):
        """
        Tries to change value of given parameter from this configuration and expects that it will be impossible.
        :param dist_name: dist name of Managed Object which contains given parameter;
                          two formats are allowed:
                          1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                          2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                             MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
        :param param: name of parameter for which value will be set
        :param value: new value of parameter which will be set
        :raises UnexpectedConfig: if setting new parameter value is possible and doesn't result in error
        """
        dist_name = self._format_dist_name(dist_name)
        log_info(f'Setting value in config which should result in error: dist_name={dist_name}, param={param}, value={value}', to_console=True)

        delta = [{'distName': dist_name,
                  'operation': 'update',
                  'parameters': [{'parameterName': param,
                                  'operation': 'update',
                                  'value': value}]}]
        delta = str(delta).replace('\'', '\"')
        api_response = self._api.perform_delta_recommissioning(delta_file=delta,
                                                               wait_for_completion=False,
                                                               should_activate=True,
                                                               vdu_connection=self._api_alias)
        recommissioning_was_impossible = wait_for(expected_value='failure',
                                                  abort_if='success',
                                                  timeout=120,
                                                  callback=self._get_status_of_delta_recommissioning,
                                                  operation_id=api_response['id'],
                                                  should_activate=True)

        if recommissioning_was_impossible:
            log_debug('Setting value in config resulted in error as expected')
        else:
            raise UnexpectedConfig('Setting value in config did not result in error as it should')

    @pretty_log
    def add(self, dist_name: str, object_name: str, params_values: Dict[str, str] = None, wait: bool = True):
        """
        Adds new Managed Object under given dist name to this configuration.
        If parameters values are also specified then object will be added with these values.
        All changes will be done at once in a single configuration plan.
        If object is already added and parameters values are not specified then nothing will be done.
        If object is already added with same parameters values as specified then nothing will be done.
        If object is already added but any parameter value is different from specified one then it will be changed.
        :param dist_name: dist name of Managed Object under which new object should be added;
                          two formats are allowed:
                          1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                          2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                             MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
        :param object_name: name of Managed Object which should be added, i.e. 'NRECPRI-1'
        :param params_values: parameter names and their values which should be set for this object;
                              i.e. {'actFdmScheduling': 'true',
                                    'actFdmEnhancedScheduling': 'false'}
        :param wait: defines whether to wait for successful recommissioning;
                     use False if adding object will result in DU reset, True otherwise;
                     defaults to True
        :raises UnexpectedConfig: when dist name, under which new object should be added, doesn't exist
        :raises TimeExceeded: if any step of adding new object exceeds defined timeout
        :raises ResultError: if any step of adding new object fails
        """
        dist_name = self._format_dist_name(dist_name)
        log_info(f'Adding object to config: dist_name={dist_name}, object_name={object_name}', to_console=True)

        self._check_if_object_exist(dist_name)
        object_full_dist_name = f'{dist_name}/{object_name}'
        object_already_added = self._does_object_exist(object_full_dist_name)
        delta = []

        if not object_already_added:
            self._add_object_creation_to_delta(delta, object_full_dist_name, params_values)
        elif object_already_added and params_values:
            params_values = [{'dist_name': object_full_dist_name,
                              'param': param,
                              'value': value} for param, value in params_values.items()]
            params_values_to_set = self._get_params_values_not_set_yet(params_values)

            if params_values_to_set:
                log_debug(f'Object already added but params values need to be set: dist_name={dist_name}, object_name={object_name}')
                self._add_object_update_to_delta(delta, object_full_dist_name, params_values_to_set)
            else:
                log_debug(f'Object already added: dist_name={dist_name}, object_name={object_name}')

        if delta:
            self._perform_delta_recommissioning(delta, wait=wait)

    @pretty_log
    def remove(self, dist_name: str):
        """
        Removes existing Managed Object with given dist name from this configuration.
        If object doesn't exist then nothing will be done.
        :param dist_name: dist name of Managed Object which should be removed;
                          two formats are allowed:
                          1) full dist name, i.e. 'MRBTS-1/NRBTS-1/NRDU-1'
                          2) partial dist name, i.e. 'MRBTS-{}/NRBTS-{}/NRDU-1' -
                             MRBTS ID and NRBTS ID will be filled automatically, works only for this two IDs
        :raises TimeExceeded: if any step of removing object exceeds defined timeout
        :raises ResultError: if any step of removing object fails
        """
        dist_name = self._format_dist_name(dist_name)
        log_info(f'Removing object from config: dist_name={dist_name}', to_console=True)

        if not self._does_object_exist(dist_name):
            log_debug(f'Object already removed: dist_name={dist_name}')
            return

        delta = [{'distName': dist_name,
                  'operation': 'delete',
                  'parameters': []}]
        self._perform_delta_recommissioning(delta)

    @pretty_log
    def recommission(self, scf_path: str, timeout: int = 300, wait_for_completion: bool = True,
                     should_activate: bool = True):
        """
        Recommissions whole configuration on DU from given SCF file.
        :param scf_path: absolute path to SCF file which will be used during recommissioning;
                         i.e. '/home/ute/scf/nrdu_1_scf.xml'
        :param timeout: timeout for recommissioning process; defaults to 300 seconds
        :param wait_for_completion: if set to True, the keyword will wait for the operation to finish; defaults to True
        :param should_activate: if set to True, plan will be activated, otherwise it will be validated without
                                activation. In order to activate the pre-validated plan user should call
                                recommission again with should_activate set to True.; defaults to True
        """
        log_info(f'Recommissioning DU config from SCF file {scf_path}', to_console=True)
        self._api.perform_commissioning(scf_file=scf_path,
                                        vdu_connection=self._api_alias,
                                        timeout=timeout,
                                        wait_for_completion=wait_for_completion,
                                        should_activate=should_activate)

    @pretty_log
    def save(self, scf_path: str, include_runtime_data: bool = True):
        """
        Saves current DU configuration to SCF file.
        :param scf_path: absolute path to SCF file where current configuration will be saved;
                         i.e. '/home/ute/scf/nrdu_1_scf.xml'
        :param include_runtime_data: if set to True, runtime data will be included in the SCF file; defaults to True
        """
        log_info(f'Saving DU config to SCF file {scf_path}', to_console=True)
        self._api.get_current_plan_file(local_dir_path='/'.join(scf_path.split('/')[:-1]),
                                        filename=scf_path.split('/')[-1],
                                        include_runtime_data=include_runtime_data,
                                        vdu_connection=self._api_alias)

    @staticmethod
    def _unpack_values_read_from_api(api_objects: Dict, unpacked_values: Dict):
        for api_object in api_objects['objects']:
            unpacked_values[api_object['distName']] = loads(api_object['json_repr'])

    def _get_params_values_not_set_yet(self, params_values: List[Dict[str, str]]) -> List[Dict[str, str]]:
        params_values_not_set = []

        for param_value in params_values:
            dist_name = self._format_dist_name(param_value['dist_name'])
            param = param_value['param']
            value = param_value['value']

            if self._is_value_already_set(value, param, dist_name):
                log_debug(f'Value already set: dist_name={dist_name}, param={param}, value={value}')
                continue
            else:
                params_values_not_set.append(param_value)

        return params_values_not_set

    def _is_value_already_set(self, value: str, param: str, dist_name: str) -> bool:
        try:
            current_value = self._api.search_parameter_of_current_plan(para_name=param,
                                                                       mo_dn=dist_name,
                                                                       vdu_connection=self._api_alias)
            return current_value == value
        except WrongApiResponseStatus:
            return False

    def _check_if_object_exist(self, dist_name: str):
        if not self._does_object_exist(dist_name):
            raise UnexpectedConfig(f'Object {dist_name} does not exist in current BTS configuration')

    def _does_object_exist(self, dist_name: str) -> bool:
        api_response = self._api.get_current_plan_objects(dist_names=[dist_name], vdu_connection=self._api_alias)
        return True if api_response['objects'] else False

    @staticmethod
    def _add_object_creation_to_delta(delta: List[Dict], dist_name: str, params_values: Dict[str, str]):
        params_values = [{'parameterName': param,
                          'operation': 'create',
                          'value': value} for param, value in params_values.items()] if params_values else []
        delta.append({'distName': dist_name,
                      'operation': 'create',
                      'parameters': params_values})

    @staticmethod
    def _add_object_update_to_delta(delta: List[Dict], dist_name: str, params_values: List[Dict[str, str]]):
        params_values = [{'parameterName': param_value['param'],
                          'operation': 'update',
                          'value': param_value['value']} for param_value in params_values]
        delta.append({'distName': dist_name,
                      'operation': 'update',
                      'parameters': params_values})

    def _perform_delta_recommissioning(self, delta: List[Dict], wait: bool = True):
        log_debug(f'Performing delta recommissioning:\n{delta}')
        delta = str(delta).replace('\'', '\"')
        api_response = self._api.perform_delta_recommissioning(delta_file=delta,
                                                               wait_for_completion=False,
                                                               should_activate=True,
                                                               timeout=600,
                                                               vdu_connection=self._api_alias)
        if wait:
            wait_for(expected_value='success',
                     abort_if='failure',
                     timeout=300,
                     callback=self._get_status_of_delta_recommissioning,
                     operation_id=api_response['id'],
                     should_activate=True)

    def _get_status_of_delta_recommissioning(self, operation_id: str, should_activate: bool) -> str:
        api_response = self._api.get_status_of_perform_delta_recommissioning(operation_id=operation_id,
                                                                             should_activate=should_activate,
                                                                             vdu_connection=self._api_alias)
        return api_response['status']
